#include <bits/stdc++.h>
using namespace std;

typedef long long ll;

ll modpow(ll a, ll n, ll mod) {
    ll res = 1;
    while (n) {
        if (n & 1) res = res * a % mod;
        a = a * a % mod;
        n >>= 1;
    }
    return res;
}

int main() {
    ll a, b, p, x;
    cin >> a >> b >> p >> x;

    // Find the period of a^n mod p
    ll period = 1;
    ll cur = a % p;
    while (cur != 1) {
        cur = cur * a % p;
        period++;
    }

    // For each residue r in [0, period-1], find the smallest n such that n*a^n ≡ b (mod p)
    // n = k*period + r, we need to find k such that (k*period + r)*a^r ≡ b (mod p)
    // => k*period*a^r + r*a^r ≡ b (mod p)
    // => k*period*a^r ≡ (b - r*a^r) (mod p)
    // If period*a^r ≡ 0 (mod p), then we need (b - r*a^r) ≡ 0 (mod p)
    // Otherwise, k ≡ (b - r*a^r) * inv(period*a^r) (mod p)

    ll count = 0;
    for (ll r = 0; r < period; r++) {
        ll ar = modpow(a, r, p);
        ll lhs = (b - r * ar % p + p) % p;
        ll coeff = period * ar % p;
        if (coeff == 0) {
            if (lhs == 0) {
                // Any k works, n = k*period + r, 1 <= n <= x
                // k*period + r >= 1 => k >= (1 - r + period - 1) / period if r > 0, else k >= 1/period => k >= 0 but n >= 1
                // k*period + r <= x => k <= (x - r) / period
                ll kmin, kmax;
                if (r == 0) {
                    kmin = 1; // n = k*period >= 1 => k >= 1
                } else {
                    kmin = 0; // n = r >= 1
                }
                kmax = (x - r) / period;
                if (kmax >= kmin) {
                    count += (kmax - kmin + 1);
                }
            }
        } else {
            ll inv_coeff = modpow(coeff, p - 2, p);
            ll k0 = lhs * inv_coeff % p;
            // n = k*period + r, k ≡ k0 (mod p)
            // Find smallest k >= kmin such that k ≡ k0 (mod p)
            ll kmin;
            if (r == 0) {
                kmin = 1;
            } else {
                kmin = 0;
            }
            // k = k0 + t*p, find smallest t such that k >= kmin
            ll t = 0;
            if (k0 < kmin) {
                t = (kmin - k0 + p - 1) / p;
            }
            ll k_start = k0 + t * p;
            // n = k_start * period + r
            if (k_start * period + r > x) continue;
            // Find largest k = k0 + t*p such that k*period + r <= x
            ll kmax = (x - r) / period;
            if (kmax < k_start) continue;
            ll tmax = (kmax - k0) / p;
            ll k_end = k0 + tmax * p;
            if (k_end < k_start) continue;
            count += (tmax - t + 1);
        }
    }

    cout << count << endl;
    return 0;
}
