#include <bits/stdc++.h>
using namespace std;

using ll = long long;

ll modpow(ll a, ll b, ll mod) {
    ll res = 1;
    a %= mod;
    while (b) {
        if (b & 1) res = res * a % mod;
        a = a * a % mod;
        b >>= 1;
    }
    return res;
}

int main() {
    ll a, b, p, x;
    cin >> a >> b >> p >> x;

    // We need to find n in [1, x] such that n * a^n ≡ b (mod p)
    // Since p is prime, a^(p-1) ≡ 1 (mod p) (Fermat's little theorem)
    // So a^n mod p has period (p-1)
    // Let's iterate over all possible residues of n mod (p-1)
    // For each residue r in [0, p-2], we compute a^r mod p
    // Then for n ≡ r (mod p-1), a^n ≡ a^r (mod p)
    // So we need n * a^r ≡ b (mod p)
    // => n ≡ b * inv(a^r) (mod p)
    // But n ≡ r (mod p-1)
    // So we solve the system:
    // n ≡ r (mod p-1)
    // n ≡ b * inv(a^r) (mod p)
    // Using CRT (Chinese Remainder Theorem)

    ll period = p - 1;
    ll count = 0;

    // Precompute a^r mod p for r in [0, period-1]
    // Actually, we can compute on the fly
    ll ar = 1; // a^0 = 1
    for (ll r = 0; r < period; r++) {
        // n ≡ r (mod period)
        // n * ar ≡ b (mod p)
        // n ≡ b * inv(ar) (mod p)
        // But if ar == 0, then we need b ≡ 0 (mod p), but b < p and b >= 1, so ar != 0
        // Since a and p are coprime (a < p, p prime), ar != 0

        ll inv_ar = modpow(ar, p - 2, p); // Fermat's little theorem
        ll n_mod_p = (b * inv_ar) % p;

        // Now solve:
        // n ≡ r (mod period)
        // n ≡ n_mod_p (mod p)
        // Since gcd(period, p) = gcd(p-1, p) = 1, CRT applies

        // n = r + k * period
        // r + k * period ≡ n_mod_p (mod p)
        // k * period ≡ (n_mod_p - r) (mod p)
        // k ≡ (n_mod_p - r) * inv(period) (mod p)

        ll rhs = (n_mod_p - r % p + p) % p;
        ll inv_period = modpow(period % p, p - 2, p);
        ll k = (rhs * inv_period) % p;

        // n = r + k * period
        // But we need n >= 1 and n <= x
        // Also, n ≡ r (mod period), so n = r + t * period for t >= 0
        // The smallest n is r + k * period (if r + k * period >= 1)
        // Wait, let me reconsider.

        // n ≡ r (mod period) means n = r + t * period for some integer t >= 0
        // n ≡ n_mod_p (mod p) means n = n_mod_p + s * p for some integer s >= 0
        // By CRT, the solution is n ≡ n0 (mod period * p) where n0 is the unique solution

        // n0 = r + k * period where k is as computed above
        ll n0 = r + k * period;

        // Now n = n0 + m * (period * p) for m >= 0
        // We need 1 <= n <= x
        // n0 + m * (period * p) <= x
        // m <= (x - n0) / (period * p)

        if (n0 <= x) {
            ll lcm = period * p; // since gcd(period, p) = 1
            ll m_max = (x - n0) / lcm;
            count += (m_max + 1);
        }

        // Update ar for next iteration: ar = a^(r+1) mod p
        ar = ar * a % p;
    }

    cout << count << endl;
    return 0;
}
